// ─── LOCALSTORAGE HELPERS ─────────────────────────────────────────────────────
const LS_KEY = 'careland_data_v1';
function loadData() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    // Try to restore images from sessionStorage
    try {
      const imgRaw = sessionStorage.getItem(LS_KEY+'_imgs');
      if (imgRaw) {
        const imgData = JSON.parse(imgRaw);
        if (data.prods && imgData.prodImgs) data.prods = data.prods.map((p,i)=>({...p,imgs:imgData.prodImgs[i]||[]}));
        if (data.trays && imgData.trayImgs) data.trays = data.trays.map((p,i)=>({...p,imgs:imgData.trayImgs[i]||[]}));
        if (data.sets && imgData.setImgs) data.sets = data.sets.map((p,i)=>({...p,imgs:imgData.setImgs[i]||[]}));
        if (data.feedbacks && imgData.fbImgs) data.feedbacks = data.feedbacks.map((f,i)=>({...f,img:imgData.fbImgs[i]||''}));
        if (data.certs && imgData.certImgs) data.certs = data.certs.map((c,i)=>({...c,img:imgData.certImgs[i]||''}));
      }
    } catch(e2) {}
    return data;
  } catch(e) { return null; }
}
function saveData(data) {
  try {
    // Save only non-image fields to avoid localStorage size limit
    const slim = {
      cats: data.cats,
      catalogs: data.catalogs,
      prods: data.prods ? data.prods.map(p=>({...p, imgs:[]})) : [],
      trays: data.trays ? data.trays.map(p=>({...p, imgs:[]})) : [],
      sets: data.sets ? data.sets.map(p=>({...p, imgs:[]})) : [],
      feedbacks: data.feedbacks ? data.feedbacks.map(f=>({...f, img:''})) : [],
      certs: data.certs ? data.certs.map(c=>({...c, img:''})) : [],
    };
    localStorage.setItem(LS_KEY, JSON.stringify(slim));
    // Save images separately in sessionStorage (persists until tab close)
    try {
      const imgData = {
        prodImgs: data.prods ? data.prods.map(p=>p.imgs||[]) : [],
        trayImgs: data.trays ? data.trays.map(p=>p.imgs||[]) : [],
        setImgs: data.sets ? data.sets.map(p=>p.imgs||[]) : [],
        fbImgs: data.feedbacks ? data.feedbacks.map(f=>f.img||'') : [],
        certImgs: data.certs ? data.certs.map(c=>c.img||'') : [],
      };
      sessionStorage.setItem(LS_KEY+'_imgs', JSON.stringify(imgData));
    } catch(e2) {}
  } catch(e) {}
}


